// scu1_ast2700_v1::CPTRA_CTRL Caliptra Control and Status Register (SCU1 +0x130). Lower bits are BootMCU-writable control; upper bits are read-only Caliptra status signals.
const (
    // PWRGOOD Caliptra power-good signal (BootMCU write). 1 = assert PWRGOOD to Caliptra; begins Caliptra internal boot. Written by SoC ROM at early boot; BootMCU FMC reads status only.
    Scu1Ast2700V1CPTRACTRLPWRGOODPos = 0
    Scu1Ast2700V1CPTRACTRLPWRGOODMsk = 0x1 << 0
    // BOOTFSMBKPT BootFSM breakpoint enable (BootMCU write, debug use). 1 = halt Caliptra BootFSM at the next breakpoint.
    Scu1Ast2700V1CPTRACTRLBOOTFSMBKPTPos = 1
    Scu1Ast2700V1CPTRACTRLBOOTFSMBKPTMsk = 0x1 << 1
    // TRNGDATA TRNG data available bits (BootMCU write). Written by BootMCU when providing external TRNG entropy. See IFC TRNG registers for the data path.
    Scu1Ast2700V1CPTRACTRLTRNGDATAPos = 2
    Scu1Ast2700V1CPTRACTRLTRNGDATAMsk = 0x3 << 2
    // SECURESTATE Security lifecycle state (BootMCU write). [10:8] = security state encoding.
    Scu1Ast2700V1CPTRACTRLSECURESTATEPos = 8
    Scu1Ast2700V1CPTRACTRLSECURESTATEMsk = 0x7 << 8
    // RDYFORFUSE Caliptra ready for fuse data (read-only). 1 = Caliptra BootFSM is waiting for fuse values from SoC. SoC ROM handles fuse delivery; FMC monitors this for diagnostics.
    Scu1Ast2700V1CPTRACTRLRDYFORFUSEPos = 16
    Scu1Ast2700V1CPTRACTRLRDYFORFUSEMsk = 0x1 << 16
    // RDYFORFW Caliptra ready for firmware (read-only). 1 = Caliptra has completed ROM verification and awaits FW upload.
    Scu1Ast2700V1CPTRACTRLRDYFORFWPos = 17
    Scu1Ast2700V1CPTRACTRLRDYFORFWMsk = 0x1 << 17
    // RDYFORRT Caliptra runtime ready (read-only mirror). 1 = Caliptra FMC+RT firmware has started; mailbox commands accepted. Mirror of IFC FLOW_STS[29].  Faster to poll than reading over the Caliptra APB bus. BootMCU FMC waits for this bit before issuing mailbox commands.
    Scu1Ast2700V1CPTRACTRLRDYFORRTPos = 18
    Scu1Ast2700V1CPTRACTRLRDYFORRTMsk = 0x1 << 18
    // MBOXDATAAVAIL Caliptra mailbox data available (read-only). 1 = Caliptra has written response data to the mailbox DATAOUT FIFO.
    Scu1Ast2700V1CPTRACTRLMBOXDATAAVAILPos = 19
    Scu1Ast2700V1CPTRACTRLMBOXDATAAVAILMsk = 0x1 << 19
    // MBOXFLOWDONE Caliptra mailbox flow done (read-only). 1 = a mailbox command has completed (success or failure).
    Scu1Ast2700V1CPTRACTRLMBOXFLOWDONEPos = 20
    Scu1Ast2700V1CPTRACTRLMBOXFLOWDONEMsk = 0x1 << 20
    // FATALERR Caliptra fatal error (read-only). 1 = Caliptra has encountered an unrecoverable hardware error. Check IFC HW_ERROR_FATAL register for details.
    Scu1Ast2700V1CPTRACTRLFATALERRPos = 21
    Scu1Ast2700V1CPTRACTRLFATALERRMsk = 0x1 << 21
    // NFATALERR Caliptra non-fatal error (read-only). 1 = Caliptra has encountered a recoverable firmware error.
    Scu1Ast2700V1CPTRACTRLNFATALERRPos = 22
    Scu1Ast2700V1CPTRACTRLNFATALERRMsk = 0x1 << 22
    // TRNGREQ Caliptra TRNG entropy request (read-only). 1 = Caliptra is requesting external entropy. BootMCU should write 12 words to IFC TRNG_DATA and set TRNG_STS.DATA_WR_DONE. Mirror of IFC TRNG_STS.DATA_REQ.
    Scu1Ast2700V1CPTRACTRLTRNGREQPos = 23
    Scu1Ast2700V1CPTRACTRLTRNGREQMsk = 0x1 << 23
)

