    SliAst2700V1CTRLIIREGTXCTRLPKTFORMPos = 4
    SliAst2700V1CTRLIIREGTXCTRLPKTFORMMsk = 0x7 << 4
    // NOTRAFFICPERIOD No-traffic connection-check period selection.
