    // PADDLY0 Pad delay for RX lane 0 (6-bit value, 0–63). Used on all sub-channels (SLIM/SLIH/SLIV).
    SliAst2700V1CTRLIIIPADDLY0Pos = 0
    SliAst2700V1CTRLIIIPADDLY0Msk = 0x3f << 0
