    SliAst2700V1CTRLIIIPADDLY2Pos = 12
    SliAst2700V1CTRLIIIPADDLY2Msk = 0x3f << 12
    // PADDLY3 Pad delay for lane 3 / TX lane 1 (6-bit value, 0–63). SLIH/SLIV: TX lane 1 (PAD_DLY_TX1). SLIM:      RX lane 3 (PAD_DLY_RX3).
    SliAst2700V1CTRLIIIPADDLY3Pos = 18
    SliAst2700V1CTRLIIIPADDLY3Msk = 0x3f << 18
