// sli_ast2700_v1::INTR SLI interrupt status / enable bits. Used by both INTR_EN and INTR_STATUS with the same bit positions. In INTR_STATUS: bits are set by hardware and cleared by writing 1. In INTR_EN: write 1 to enable the corresponding INTR_STATUS bit.
const (
    // RXIDLE RX is idle (no incoming data).
    SliAst2700V1INTRRXIDLEPos = 0
    SliAst2700V1INTRRXIDLEMsk = 0x1 << 0
    // RXSUSPEND RX has entered suspend state. Poll together with TX_SUSPEND to confirm both sides are suspended before issuing CLEAR_BUS or changing pad delays.
    SliAst2700V1INTRRXSUSPENDPos = 1
    SliAst2700V1INTRRXSUSPENDMsk = 0x1 << 1
    // TXIDLE TX is idle (no pending transactions).
    SliAst2700V1INTRTXIDLEPos = 2
    SliAst2700V1INTRTXIDLEMsk = 0x1 << 2
    // TXTRAIN TX is actively sending training packets.
    SliAst2700V1INTRTXTRAINPos = 3
    SliAst2700V1INTRTXTRAINMsk = 0x1 << 3
    // TXSUSPEND TX has entered suspend state. Set after CLEAR_BUS or link idle; cleared automatically on restart. Used together with RX_SUSPEND to confirm a clean idle state.
    SliAst2700V1INTRTXSUSPENDPos = 4
    SliAst2700V1INTRTXSUSPENDMsk = 0x1 << 4
    SliAst2700V1INTRRXFIFOOVERFLOWPos = 5
    SliAst2700V1INTRRXFIFOOVERFLOWMsk = 0x1 << 5
    // RXDISCONN RX disconnection detected. Remote peer stopped transmitting.
    SliAst2700V1INTRRXDISCONNPos = 6
    SliAst2700V1INTRRXDISCONNMsk = 0x1 << 6
    SliAst2700V1INTRTXTRAINSDONEPos = 7
    SliAst2700V1INTRTXTRAINSDONEMsk = 0x1 << 7
    SliAst2700V1INTRREGREADDONEPos = 8
    SliAst2700V1INTRREGREADDONEMsk = 0x1 << 8
    SliAst2700V1INTRREGWRITEDONEPos = 9
    SliAst2700V1INTRREGWRITEDONEMsk = 0x1 << 9
    // RXTRAINPKT RX training packet received during calibration.
    SliAst2700V1INTRRXTRAINPKTPos = 10
    SliAst2700V1INTRRXTRAINPKTMsk = 0x1 << 10
    SliAst2700V1INTRRXACKPKTPos = 11
    SliAst2700V1INTRRXACKPKTMsk = 0x1 << 11
    // RXNACK RX NACK received from remote peer. Indicates the remote end rejected a transaction.
    SliAst2700V1INTRRXNACKPos = 12
    SliAst2700V1INTRRXNACKMsk = 0x1 << 12
    // RXERR RX data error detected. Indicates a receive-side protocol error. Link must be reset.
    SliAst2700V1INTRRXERRPos = 13
    SliAst2700V1INTRRXERRMsk = 0x1 << 13
    SliAst2700V1INTRREGREADFAILEDPos = 14
    SliAst2700V1INTRREGREADFAILEDMsk = 0x1 << 14
    // RXSYNC RX synchronisation achieved (link training complete).
    SliAst2700V1INTRRXSYNCPos = 15
    SliAst2700V1INTRRXSYNCMsk = 0x1 << 15
    SliAst2700V1INTRBUSREADFIFOOVERFLOWPos = 16
    SliAst2700V1INTRBUSREADFIFOOVERFLOWMsk = 0x1 << 16
    // ACKSYSERR ACK response reported system error.
    SliAst2700V1INTRACKSYSERRPos = 17
    SliAst2700V1INTRACKSYSERRMsk = 0x1 << 17
    // MBIDLOSS SLIM CPU-die MBID loss interrupt.
    SliAst2700V1INTRMBIDLOSSPos = 18
    SliAst2700V1INTRMBIDLOSSMsk = 0x1 << 18
    SliAst2700V1INTRRXPHYFIFOOVERFLOWPos = 24
    SliAst2700V1INTRRXPHYFIFOOVERFLOWMsk = 0x1 << 24
    SliAst2700V1INTRTXPHYFIFOUNDERFLOWPos = 25
    SliAst2700V1INTRTXPHYFIFOUNDERFLOWMsk = 0x1 << 25
)

